#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_spi.h"

#define SPI_MASTER          SPI0
#define SPI_MASTER_CLK_SRC  kCLOCK_BusClk
#define SPI_CS_GPIO         GPIOC
#define SPI_CS_PIN          5u

int main(void)
{
    /* 1. Enable clocks for PORTC and SPI0 */
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_Spi0);

    /* 2. Configure pin mux for SPI0 */
    PORT_SetPinMux(PORTC, 6u, kPORT_MuxAlt2);  /* PTC6: SPI0_SCK */
    PORT_SetPinMux(PORTC, 7u, kPORT_MuxAlt2);  /* PTC7: SPI0_MOSI */
    PORT_SetPinMux(PORTC, 4u, kPORT_MuxAlt2);  /* PTC4: SPI0_MISO */

    /* 3. Configure manual CS pin PTC5 as GPIO output */
    PORT_SetPinMux(PORTC, 5u, kPORT_MuxAsGpio);

    gpio_pin_config_t cs_pin_config = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = 1u  /* CS idle high */
    };
    GPIO_PinInit(SPI_CS_GPIO, SPI_CS_PIN, &cs_pin_config);

    /* 4. SPI0 master configuration */
    spi_master_config_t masterConfig;
    SPI_MasterGetDefaultConfig(&masterConfig);
    masterConfig.baudRate_Bps = 1000000;          /* 1 MHz */
    masterConfig.dataWidth    = kSPI_Data8Bits;   /* 8-bit frame */
    masterConfig.polarity     = kSPI_ClockPolarityActiveHigh; /* CPOL=0 */
    masterConfig.phase        = kSPI_ClockPhaseFirstEdge;     /* CPHA=0 */

    /* 5. Initialize SPI0 */
    SPI_MasterInit(SPI_MASTER, &masterConfig, CLOCK_GetFreq(SPI_MASTER_CLK_SRC));

    /* 6. Prepare the 2-byte transfer */
    uint8_t txBuffer[2] = {0x9F, 0x00};
    uint8_t rxBuffer[2] = {0x00, 0x00};

    spi_transfer_t masterXfer;
    masterXfer.txData      = txBuffer;
    masterXfer.rxData      = rxBuffer;
    masterXfer.dataSize    = 2;
    masterXfer.configFlags = 0;  /* Using manual CS, so no hardware PCS flags */

    /* 7. Assert CS low before transfer */
    GPIO_PinWrite(SPI_CS_GPIO, SPI_CS_PIN, 0u);

    /* 8. Perform blocking transfer */
    SPI_MasterTransferBlocking(SPI_MASTER, &masterXfer);

    /* 9. Deassert CS high after transfer */
    GPIO_PinWrite(SPI_CS_GPIO, SPI_CS_PIN, 1u);

    /* Main loop */
    while (1)
    {
        __WFI();
    }
}

