/* Approximate 1 ms busy-wait based on the CMSIS SystemCoreClock variable.
 * Each loop iteration is roughly a handful of cycles on Cortex-M0+.
 */
static void delay_ms(uint32_t ms)
{
    volatile uint32_t cycles = (SystemCoreClock / 1000U) * ms / 4U;

    while (cycles-- != 0U)
    {
        __NOP();
    }
}

int main(void)
{
    /* Enable the clock gates for PORTA and UART0 before use. */
    CLOCK_EnableClock(kCLOCK_PortA);
    CLOCK_EnableClock(kCLOCK_Uart0);

    /* PTA1 = UART0_RX, PTA2 = UART0_TX (ALT2). */
    PORT_SetPinMux(PORTA, 1U, kPORT_MuxAlt2);
    PORT_SetPinMux(PORTA, 2U, kPORT_MuxAlt2);

    uart_config_t uartConfig;
    UART_GetDefaultConfig(&uartConfig);
    uartConfig.baudRate_Bps  = 115200U;
    uartConfig.parityMode    = kUART_ParityDisabled;
    uartConfig.stopBitCount  = kUART_OneStopBit;
    uartConfig.enableTx      = true;
    uartConfig.enableRx      = true;

    status_t status = UART_Init(UART0,
                                 &uartConfig,
                                 CLOCK_GetCoreSysClkFreq());
    if (status != kStatus_Success)
    {
        /* Initialization failed: halt. */
        while (1)
        {
            __NOP();
        }
    }

    static const uint8_t message[] = "Hello\r\n";

    for (;;)
    {
        UART_WriteBlocking(UART0, message, sizeof(message) - 1U);
        delay_ms(1000U);
    }

    /* Never reached. */
    return 0;
}

