#include"fsl_common.h"
#include "fsl_clock.h"
#include "fsl_edma.h"

#define BUFF_LENGTH 512U

/* 
 * Place buffers in a non-cacheable section to avoid data cache coherency issues 
 * with DMA on the Cortex-M7 core.
 */
AT_NONCACHEABLE_SECTION_INIT(uint8_t src[BUFF_LENGTH]);
AT_NONCACHEABLE_SECTION_INIT(uint8_t dst[BUFF_LENGTH]);

int main(void)
{
    /* 1. Enable the DMA0 peripheral clock gate before initializing the peripheral */
    CLOCK_EnableClock(kCLOCK_Dma0);

    /* 2. Fill the source buffer with the byte pattern (index & 0xFF) */
    for (uint32_t i = 0; i < BUFF_LENGTH; i++)
    {
        src[i] = (uint8_t)(i & 0xFFU);
        dst[i] = 0U;
    }

    /* 3. Initialize eDMA peripheral with default configuration */
    edma_config_t edmaConfig;
    EDMA_GetDefaultConfig(&edmaConfig);
    EDMA_Init(DMA0, &edmaConfig);

    /* 4. Create eDMA handle for DMA0 channel 0 */
    edma_handle_t edmaHandle;
    EDMA_CreateHandle(&edmaHandle, DMA0, 0);

    /* 5. Prepare the memory-to-memory transfer configuration */
    edma_transfer_config_t transferConfig;
    EDMA_PrepareTransfer(&transferConfig,
                         src,                  /* source address */
                         1,                    /* source width (1 byte) */
                         dst,                  /* destination address */
                         1,                    /* destination width (1 byte) */
                         BUFF_LENGTH,           /* bytes per transfer (minor loop) */
                         BUFF_LENGTH,           /* total bytes (major loop) */
                         kEDMA_MemoryToMemory); /* transfer type */

    /* 6. Submit and start the transfer */
    EDMA_SubmitTransfer(&edmaHandle, &transferConfig);
    EDMA_StartTransfer(&edmaHandle);

    /* 7. Wait for the transfer to complete by polling the DONE flag */
    while ((EDMA_GetChannelStatusFlags(DMA0, 0) & kEDMA_DoneFlag) == 0U)
    {
        /* Wait */
    }

    /* Clear the done flag */
    EDMA_ClearChannelStatusFlags(DMA0, 0, kEDMA_DoneFlag);

    /* 8. Compare destination and source; halt in an infinite loop on mismatch */
    for (uint32_t i = 0; i < BUFF_LENGTH; i++)
    {
        if (dst[i] != src[i])
        {
            /* Mismatch found, halt */
            while (1)
            {
                __NOP();
            }
        }
    }

    /* Success: halt in an infinite loop */
    while (1)
    {
        __NOP();
    }
}

