#define LED_GPIO    GPIO9
#define LED_PIN     3U
#define LED_OFF     1U  /* Assuming active-low LED */
#define LED_ON      0U

static void DelayMS(volatile uint32_t ms)
{
    /* Rough software delay for i.MX RT1170 running at a high clock frequency.
       The exact delay depends on the CPU clock and compiler optimization level.
       Tuned to be approximately 500ms for a ~600 MHz Cortex-M7 core. */
    for (volatile uint32_t i = 0; i < ms * 10000U; ++i)
    {
        __NOP();
    }
}

int main(void)
{
    /* Enable clock gate for GPIO9 peripheral */
    CLOCK_EnableClock(kCLOCK_Gpio9);

    /* Configure pad GPIO_AD_04 as GPIO9_IO03 */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_04_GPIO9_IO03, 0U);

    /* Initialize GPIO9 pin 3 as digital output, LED off at startup */
    gpio_pin_config_t led_config = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = LED_OFF,
    };
    GPIO_PinInit(LED_GPIO, LED_PIN, &led_config);

    /* Main loop: toggle LED roughly every 500 ms */
    while (1)
    {
        GPIO_PortToggle(LED_GPIO, 1U << LED_PIN);
        DelayMS(500);
    }
}

