#define SENSOR_I2C          LPI2C1
#define SENSOR_I2C_CLK_FREQ 24000000U
#define SENSOR_ADDR         0x68U
#define WHO_AM_I_REG        0x75U

uint8_t g_who_am_i = 0U;

int main(void)
{
    /* Enable LPI2C1 clock gate */
    CLOCK_EnableClock(kCLOCK_Lpi2c1);

    /* Configure LPI2C1 clock source (OSC24M) and divider */
    CLOCK_SetMux(kCLOCK_Lpi2c1Mux, 0);
    CLOCK_SetDiv(kCLOCK_Lpi2c1Div, 0);

    /* Configure pin mux for LPI2C1 SCL and SDA */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_08_LPI2C1_SCL, 0U);
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_09_LPI2C1_SDA, 0U);

    /* Configure pad settings for I2C: open drain, pull-up */
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_08_LPI2C1_SCL, 0x10A0U);
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_09_LPI2C1_SDA, 0x10A0U);

    /* Initialize LPI2C1 master */
    lpi2c_master_config_t masterConfig;
    LPI2C_MasterGetDefaultConfig(&masterConfig);
    masterConfig.baudRate_Hz = 400000U;
    LPI2C_MasterInit(SENSOR_I2C, &masterConfig, SENSOR_I2C_CLK_FREQ);

    /* Read WHO_AM_I register */
    lpi2c_master_transfer_t xfer;
    xfer.slaveAddress   = SENSOR_ADDR;
    xfer.direction      = kLPI2C_Read;
    xfer.subaddress     = WHO_AM_I_REG;
    xfer.subaddressSize = 1U;
    xfer.data           = &g_who_am_i;
    xfer.dataSize       = 1U;
    xfer.flags          = kLPI2C_TransferDefaultFlag;

    status_t status = LPI2C_MasterTransferBlocking(SENSOR_I2C, &xfer);
    if (status != kStatus_Success)
    {
        /* Transfer failed */
        g_who_am_i = 0xFFU;
    }

    while (1)
    {
        __WFI();
    }
}

